[
  {
    "uri": "features/refunds.feature",
    "name": "Refunds",
    "keyword": "Feature",
    "elements": [
      {
        "type": "background",
        "keyword": "Background",
        "name": "",
        "steps": [
          {
            "keyword": "Given ",
            "name": "a captured card payment of 100.00",
            "result": {
              "status": "passed",
              "duration": 120000000
            }
          }
        ]
      },
      {
        "type": "scenario",
        "keyword": "Scenario",
        "name": "Refund within the limit",
        "steps": [
          {
            "keyword": "When ",
            "name": "I refund 40.00",
            "result": {
              "status": "passed",
              "duration": 310000000
            }
          },
          {
            "keyword": "Then ",
            "name": "the refund is accepted",
            "result": {
              "status": "passed",
              "duration": 90000000
            }
          }
        ]
      },
      {
        "type": "scenario",
        "keyword": "Scenario",
        "name": "Refund above the limit is rejected",
        "steps": [
          {
            "keyword": "When ",
            "name": "I refund 150.00",
            "result": {
              "status": "passed",
              "duration": 280000000
            }
          },
          {
            "keyword": "Then ",
            "name": "the refund is rejected with \"limit exceeded\"",
            "result": {
              "status": "failed",
              "duration": 50000000,
              "error_message": "Expected status 422 but was 500"
            }
          }
        ]
      }
    ]
  }
]
